proc jsAbortControllerSignal*(self: AbortController): JsObject =
  when defined(wasm32):
    {.emit: """var ret = heap[`self`.idx].signal;
`result` = {idx: addHeapObject(ret)};""".}
  else:
    result = JsObject(JsValue(idx: 0))
proc jsAbort*(self: AbortController; reason: JsObject): void =
  when defined(wasm32):
    {.emit: "var ret = heap[`self`.idx].abort(heap[`reason`.idx]);".}
  else:
    discard

proc jsAbortSignalAborted*(self: AbortSignal): bool =
  when defined(wasm32):
    {.emit: """var ret = heap[`self`.idx].aborted;
`result` = ret ? 1 : 0;""".}
  else:
    result = false
